    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        word = ['?'] * L
        fixed = [False] * L

        # Place forced characters from 'T' constraints
        for i, c in enumerate(str1):
            if c == 'T':
                for j in range(m):
                    p = i + j
                    if fixed[p] and word[p] != str2[j]:
                        return ""
                    word[p] = str2[j]
                    fixed[p] = True

        # Fill free positions with 'a'
        for p in range(L):
            if not fixed[p]:
                word[p] = 'a'

        # Fix 'F' constraints
        for i, c in enumerate(str1):
            if c == 'F' and word[i:i + m] == list(str2):
                j = -1
                for p in range(i + m - 1, i - 1, -1):
                    if not fixed[p]:
                        j = p
                        break
                if j == -1:
                    return ""
                word[j] = 'b'

        result = ''.join(word)

